#!/usr/bin/env python3
"""Build the dependency-free catalogue and an explicit GitHub Pages allowlist."""
from html import escape
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlsplit
import argparse
import json
import re
import shutil

ROOT = Path(__file__).resolve().parents[1]
SLUG = re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*\Z")
PUBLISH_FILES = ("index.html", "LICENSE", "THIRD_PARTY_NOTICES.md", "README.md")
REQUIRED_FILES = ("index.html", "THIRD_PARTY_NOTICES.md", "README.md")


class AssetLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.runtime = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag in ("script", "img", "audio", "video", "source", "iframe", "embed"):
            self.runtime.extend(attrs[k] for k in ("src", "poster") if attrs.get(k))
        if tag == "link" and set(attrs.get("rel", "").split()) & {"stylesheet", "preload", "modulepreload"}:
            if attrs.get("href"):
                self.runtime.append(attrs["href"])


def require(condition, message):
    if not condition:
        raise ValueError(message)


def local_file(relative):
    path = ROOT / relative
    require(path.is_file() and not path.is_symlink(), f"Missing regular file: {relative}")
    require(path.resolve().is_relative_to(ROOT), f"Path escapes the repository: {relative}")
    return path


def load_demos():
    demos = json.loads((ROOT / "demos.json").read_text())['demos']
    require(isinstance(demos, list) and demos, "demos.json needs a nonempty demos list")
    seen = set()
    for demo in demos:
        slug = demo.get("slug", "")
        require(isinstance(slug, str) and SLUG.fullmatch(slug), f"Unsafe demo slug: {slug!r}")
        require(slug not in seen, f"Duplicate demo slug: {slug}")
        seen.add(slug)
        require(not (ROOT / slug).is_symlink(), f"Demo directories must not be symlinks: {slug}")
        for key in ("title", "description", "requirements"):
            require(isinstance(demo.get(key), str) and demo[key].strip(), f"{slug}: missing {key}")
        require(isinstance(demo.get("tags"), list) and all(isinstance(t, str) for t in demo["tags"]), f"{slug}: tags must be strings")
        for name in REQUIRED_FILES:
            local_file(f"{slug}/{name}")
        html = local_file(f"{slug}/index.html").read_text()
        if demo.get("license") == "MIT":
            local_file(f"{slug}/LICENSE")
            require("MIT License" in html, f"{slug}: retain the inline MIT permission notice")
        parser = AssetLinks()
        parser.feed(html)
        remote = [url for url in parser.runtime if urlsplit(url).scheme in ("http", "https") or url.startswith("//")]
        remote += re.findall(r"(?:@import\s+|url\(\s*['\"]?)(https?://[^\s)'\";]+)", html, re.I)
        require(not remote, f"{slug}: external runtime assets are not allowed: {remote}")
        preview = demo.get("preview")
        if preview:
            require(preview == f"{slug}/preview.jpg", f"{slug}: preview must be {slug}/preview.jpg")
            local_file(preview)
        if "htmlBytes" in demo:
            require(type(demo["htmlBytes"]) is int and demo["htmlBytes"] == (ROOT / slug / "index.html").stat().st_size, f"{slug}: htmlBytes differs from the deliverable")
    return demos


def render(demos):
    cards = []
    for number, demo in enumerate(demos, 1):
        slug, title = escape(demo["slug"]), escape(demo["title"])
        preview = f'<img src="./{escape(demo["preview"])}" alt="{title}: a view inside the interactive scene" width="1280" height="720" loading="lazy" decoding="async">' if demo.get("preview") else '<span class="placeholder">A world waiting to be explored</span>'
        tags = ''.join(f'<li>{escape(tag)}</li>' for tag in demo["tags"])
        size = f'<span>{demo["htmlBytes"] / 1000:.1f} KB HTML</span>' if "htmlBytes" in demo else ''
        cards.append(f'''<article class="study"><a class="preview" href="./{slug}/" aria-label="Explore {title}">{preview}<span class="number">STUDY {number:02d}</span></a><div class="details"><ul class="tags" aria-label="Techniques">{tags}</ul><h2><a href="./{slug}/">{title}</a></h2><p>{escape(demo["description"])}</p><p class="requirements">{escape(demo["requirements"])}</p><div class="actions"><a class="play" href="./{slug}/">Explore the scene <span aria-hidden="true">↗</span></a><a class="source" href="https://github.com/zixma13/shortlist/tree/main/{slug}">Source &amp; credits</a></div><div class="size">{size}<span>No external runtime assets</span></div></div></article>''')
    count = f'{len(demos):02d}'
    return '''<!doctype html>
<!-- Generated by scripts/build_site.py; edit demos.json. -->
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><meta name="description" content="Shortlist: a collection of compact, playable experiments in procedural worlds and real-time graphics."><title>Shortlist · Small files, deep worlds</title><style>
:root{font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#eaf4ed;background:#071b20;font-synthesis:none}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 88% 0,#153c3e88,transparent 48%);min-height:100vh}a{color:inherit;text-decoration:none}a:focus-visible{outline:3px solid #bcdfac;outline-offset:5px}a:hover{text-decoration:underline;text-underline-offset:5px}.wrap{max-width:1240px;margin:auto;padding:0 6vw}header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:32px 0;border-bottom:1px solid #b4dbc226}.wordmark{letter-spacing:.26em;font-size:13px;font-weight:750}.repo{font-size:12px;color:#b9cdca}.hero{padding:72px 0 62px;display:grid;grid-template-columns:1.3fr 1fr;gap:48px;align-items:end}.eyebrow{margin:0 0 20px;color:#a8d2bd;font-size:10px;letter-spacing:.22em;font-weight:650;text-transform:uppercase}h1{font-family:ui-serif,Georgia,serif;font-size:clamp(46px,5.6vw,76px);font-weight:400;line-height:1.04;letter-spacing:-.045em;margin:0}h1 em{color:#b7d8a6;font-style:normal}.intro{max-width:360px;font-size:15px;line-height:1.85;color:#b9cdca;margin:0 0 5px}.section-label{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #b4dbc226;padding:18px 0 25px;font-size:10px;color:#a8bfba;letter-spacing:.17em;text-transform:uppercase}.studies{display:grid;gap:28px}.study{display:grid;grid-template-columns:1.28fr 1fr;border:1px solid #b4dbc22e;background:#0b2529;border-radius:3px;overflow:hidden}.preview{position:relative;display:block;background:#102f35;min-height:340px;overflow:hidden}.preview img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover}.number{position:absolute;top:20px;left:20px;background:#061c23c9;padding:8px 10px;font-size:9px;letter-spacing:.18em;color:#eaf4ed;border:1px solid #c3dfcf33}.placeholder{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:30px;color:#bad4cd;background:radial-gradient(ellipse at 68% 35%,#9fbcad55,transparent 48%),linear-gradient(145deg,#123238,#050e15);font:italic 23px ui-serif,Georgia,serif}.details{padding:38px;align-self:center}.tags{display:flex;flex-wrap:wrap;gap:7px;list-style:none;padding:0;margin:0 0 23px}.tags li{font-size:9px;letter-spacing:.055em;color:#b8d2c3;border:1px solid #b4dbc22e;padding:5px 7px;border-radius:2px}h2{font-family:ui-serif,Georgia,serif;font-size:clamp(28px,3vw,38px);letter-spacing:-.035em;font-weight:400;line-height:1.12;margin:0 0 17px}.details p{font-size:13px;color:#bed0cc;line-height:1.8;margin:0 0 18px}.details .requirements{font-size:10px;color:#93ada8;line-height:1.7}.actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap;margin:27px 0}.play{font-size:11px;background:#c3dfae;color:#132820;padding:13px 17px;border-radius:2px;font-weight:650;display:inline-flex;gap:24px;align-items:center}.play:hover{background:#d3ebc0;text-decoration:none}.source{font-size:10px;color:#b7cdc4}.size{display:flex;flex-wrap:wrap;gap:14px;font-size:9px;color:#9db7ad;letter-spacing:.04em}footer{display:flex;justify-content:space-between;gap:24px;border-top:1px solid #b4dbc226;margin-top:55px;padding:27px 0 36px;color:#90aaa4;font-size:10px;line-height:1.9}footer p{margin:0;max-width:680px}footer a{color:#c0d6c8}.footnote{white-space:nowrap}@media(min-width:1400px){.wrap{padding:0 68px}}@media(max-width:760px){.hero{grid-template-columns:1fr;gap:26px;padding:48px 0 40px}.intro{max-width:460px;font-size:13px}.study{grid-template-columns:1fr}.preview{min-height:0;aspect-ratio:16/10}.details{padding:27px}.section-label{font-size:9px}footer{flex-direction:column;gap:12px}.repo{font-size:10px}header{padding:24px 0}.wordmark{font-size:11px}}@media(prefers-reduced-motion:no-preference){.preview img{transition:transform .7s ease}.preview:hover img{transform:scale(1.025)}}
</style></head><body><div class="wrap"><header><a class="wordmark" href="./" aria-label="Shortlist home">SHORTLIST</a><a class="repo" href="https://github.com/zixma13/shortlist">View on GitHub ↗</a></header><main><section class="hero" aria-labelledby="page-title"><div><p class="eyebrow">Interactive studies · An ongoing collection</p><h1 id="page-title">Small files.<br><em>Deep worlds.</em></h1></div><p class="intro">A growing collection of compact, playable experiments. Open a scene, explore, and follow the ideas behind it.</p></section><div class="section-label"><span>Selected experiments</span><span>''' + count + ''' available</span></div><section class="studies" aria-label="Playable demos">''' + ''.join(cards) + '''</section></main><footer><p>Tidal Sanctuary adapts <a href="https://github.com/Noniv/abyssal-garden">Abyssal Garden</a> (MIT). <a href="https://github.com/Humpalumps/Ultra-Water">Ultra-Water</a> informed the ocean-rendering research. Full provenance and licenses accompany each demo.</p><p class="footnote">Made to be explored.</p></footer></div></body></html>
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Validate inputs and require the committed catalogue to match the manifest")
    args = parser.parse_args()
    demos = load_demos()
    page = render(demos)
    require(len(page.encode()) < 5000 + 1400 * len(demos), "Catalogue exceeds its base plus per-demo HTML budget")
    index = ROOT / "index.html"
    if args.check:
        require(index.exists() and index.read_text() == page, "Catalogue is stale; run python3 scripts/build_site.py")
        print(f"Catalogue current; {len(demos)} demo(s), {len(page.encode())} HTML bytes; sources and notices valid.")
        return
    index.write_text(page)
    output = ROOT / "_site"
    require(not output.is_symlink(), "Refusing to replace a symlink at _site")
    if output.exists():
        shutil.rmtree(output)
    output.mkdir()
    (output / "index.html").write_text(page)
    (output / ".nojekyll").touch()
    for name in ("README.md", "LICENSE"):
        if (ROOT / name).is_file():
            shutil.copy2(local_file(name), output / name)
    for demo in demos:
        destination = output / demo["slug"]
        destination.mkdir()
        for name in PUBLISH_FILES:
            source = ROOT / demo["slug"] / name
            if source.is_file():
                shutil.copy2(local_file(f'{demo["slug"]}/{name}'), destination / name)
        if demo.get("preview"):
            shutil.copy2(local_file(demo["preview"]), destination / "preview.jpg")
    print(f"Built {len(demos)} demo(s) into {output}; catalogue {len(page.encode())} bytes.")


if __name__ == "__main__":
    try:
        main()
    except (ValueError, KeyError, json.JSONDecodeError) as error:
        raise SystemExit(str(error))
